((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
globalThis.KENGURU_GRADES_7_8 = [{"id":"2024-7-8","year":2024,"grades":[7,8],"label":"7–8 классы","tasksUrl":"https://ipokengu.ru/public/task/kenguru_2024_class_7-8.pdf","answersUrl":"https://ipokengu.ru/public/task/kenguru_2024_answers.pdf","solutionUrl":"https://ipokengu.ru/public/task/kenguru_2024_solution.pdf","answerLetters":"АБВГД","cards":[{"number":1,"title":"Пять резинок","question":"Какую из пяти резинок нельзя положить так, как показано на рисунке справа, не разрезая её?","options":[{"image":"assets/grades-7-8/2024/task-01-answer-1.svg","description":"Широкая вертикальная петля с восьмёркой внутри"},{"image":"assets/grades-7-8/2024/task-01-answer-2.svg","description":"Овальная петля сверху и две перекрещённые закруглённые петли снизу"},{"image":"assets/grades-7-8/2024/task-01-answer-3.svg","description":"Треугольный контур с пересечением наверху и плоской петлёй вдоль основания"},{"image":"assets/grades-7-8/2024/task-01-answer-4.svg","description":"Две петли слева, одна над другой, и третья справа"},{"image":"assets/grades-7-8/2024/task-01-answer-5.svg","description":"Три петли одна над другой, средняя шире верхней и нижней"}],"condition":{"src":"assets/grades-7-8/2024/task-01.svg","width":159,"height":72,"alt":"Резинка уложена горизонтальной восьмёркой из двух петель с одним пересечением."},"answer":1,"points":3,"review":[{"title":"Проследим переплетение","text":"На рисунке Б поперечный участок резинки проходит сквозь петлю. Если идти вдоль замкнутой резинки, на трёх пересечениях участки поочерёдно проходят сверху и снизу. Так выглядит узел-трилистник."},{"title":"Сравним с восьмёркой","text":"У восьмёрки справа единственное пересечение можно убрать, расправив одну петлю. Узел-трилистник на замкнутой резинке расправить без разреза нельзя."}],"keyNote":null},{"number":2,"title":"Пятиугольник в центре","question":"Фигуру на рисунке складывают из равных между собой пятиугольников. Какой из предложенных ниже пятиугольников нужно поместить в центр образовавшейся фигуры, чтобы получилось изображение двух замкнутых линий?","options":[{"image":"assets/grades-7-8/2024/task-02-answer-1.svg","description":"Одна дуга соединяет нижнюю левую сторону с верхней правой, другая — основание с нижней правой"},{"image":"assets/grades-7-8/2024/task-02-answer-2.svg","description":"Одна дуга соединяет верхнюю левую сторону с нижней правой, другая — нижнюю левую с основанием"},{"image":"assets/grades-7-8/2024/task-02-answer-3.svg","description":"Одна дуга соединяет две левые стороны, другая — верхнюю правую с основанием"},{"image":"assets/grades-7-8/2024/task-02-answer-4.svg","description":"Одна дуга соединяет верхнюю левую сторону с основанием, другая — две правые стороны"},{"image":"assets/grades-7-8/2024/task-02-answer-5.svg","description":"Одна дуга соединяет две верхние стороны, другая — две нижние боковые стороны"}],"condition":{"src":"assets/grades-7-8/2024/task-02.svg","width":295,"height":228,"alt":"Шесть пятиугольников окружают пятиугольный просвет с плоской стороной сверху и вершиной снизу. Толстая линия слева выходит к просвету на верхней горизонтальной и нижней левой сторонах. Толстая линия справа выходит к двум правым сторонам просвета."},"answer":2,"points":3,"review":[{"title":"Найдём концы линий","text":"Вокруг пустого места проходят две линии. У каждой по два конца. Чтобы получить два замкнутых контура, центральная деталь должна соединить концы каждой линии между собой."},{"title":"Повернём деталь","text":"У детали В одна дуга соединяет две соседние боковые стороны, а другая — боковую сторону с основанием. Повернём деталь вершиной вниз. Обе дуги продолжают линии вокруг просвета и замыкают их.","image":"assets/grades-7-8/2024/solution-02-1.svg","imageWidth":297,"imageHeight":228}],"keyNote":null},{"number":3,"title":"От ромба к пятиугольнику","question":"На рисунке 1 изображён ромб. К нему дорисовали два одинаковых прямоугольных треугольника так, как показано на рисунке 2, и получили пятиугольник. На сколько процентов площадь пятиугольника больше площади ромба?","options":[{"text":"20%"},{"text":"25%"},{"text":"30%"},{"text":"40%"},{"text":"50%"}],"condition":{"src":"assets/grades-7-8/2024/task-03.svg","width":209,"height":170,"alt":"Рис. 1 — ромб с вертикальной длинной диагональю. На рис. 2 два прямоугольных треугольника примыкают к нижним сторонам такого же ромба, образуя пятиугольник с горизонтальным основанием."},"answer":4,"points":3,"review":[{"title":"Разделим ромб","text":"Проведём обе диагонали ромба. Они перпендикулярны и делятся пополам в точке пересечения. Получатся четыре прямоугольных треугольника одинаковой площади."},{"title":"Сравним площади","text":"У двух дорисованных треугольников такие же катеты, как у этих четырёх. В пятиугольнике шесть равных частей, а в ромбе четыре. Прибавилось 2 из 4 исходных частей, то есть 50%.","image":"assets/grades-7-8/2024/solution-03-1.svg","imageWidth":120,"imageHeight":176}],"keyNote":null},{"number":4,"title":"Дробь с произведениями","question":"Чему равно значение выражения (20 × 24) / (2 × 0 + 2 × 4)?","options":[{"text":"12"},{"text":"30"},{"text":"48"},{"text":"60"},{"text":"120"}],"condition":null,"answer":3,"points":3,"review":[{"title":"Вычислим знаменатель","text":"2 × 0 + 2 × 4 = 0 + 8 = 8."},{"title":"Разделим произведение","text":"Чтобы разделить 20 × 24 на 8, сначала разделим 24 на 8. Получаем 20 × 3 = 60."}],"keyNote":null},{"number":5,"title":"Срезанные вершины тетраэдра","question":"Игорь обрезал все четыре вершины правильного тетраэдра (на рисунке отрезанные части закрашены тёмно-серым). Сколько вершин у получившегося многогранника?","options":[{"text":"8"},{"text":"9"},{"text":"11"},{"text":"12"},{"text":"16"}],"condition":{"src":"assets/grades-7-8/2024/task-05.svg","width":202,"height":220,"alt":"Тетраэдр, у каждой из четырёх вершин которого тёмно-серым показана отрезанная часть."},"answer":3,"points":3,"review":[{"title":"Рассмотрим один срез","text":"В каждой вершине тетраэдра сходятся три ребра. Плоскость среза пересекает все три ребра. В этих точках получаются три новые вершины."},{"title":"Сосчитаем новые вершины","text":"Все четыре старые вершины срезаны, и каждый срез даёт три вершины. Всего получается 4 × 3 = 12."}],"keyNote":null},{"number":6,"title":"Три жетона Риты","question":"У Риты есть три жетона с числами 1, 5 и 11. Она хочет положить их рядом так, чтобы получилось четырёхзначное число. Сколько различных четырёхзначных чисел она сможет составить?","options":[{"text":"3"},{"text":"4"},{"text":"6"},{"text":"8"},{"text":"9"}],"condition":null,"answer":1,"points":3,"review":[{"title":"Разместим пятёрку","text":"Жетоны 1 и 11 вместе дают три единицы, а свободных промежутков для жетона 5 четыре. Два промежутка расположены по краям. Каждый из двух внутренних промежутков можно получить, положив 5 между жетонами 1 и 11 в нужном порядке."},{"title":"Выпишем числа","text":"В зависимости от места пятёрки получаются 5111, 1511, 1151 и 1115. Это четыре различных числа."}],"keyNote":null},{"number":7,"title":"Фрукты и ягоды на тарелке","question":"На тарелке лежит пять разных фруктов и ягод: яблоко, виноград, вишня, клубника и банан.\n\nАлиса любит яблоки. Боря любит яблоки, вишню, клубнику и бананы. Коля любит виноград, вишню, клубнику и бананы. Денис любит яблоки, виноград и вишню. Ева любит яблоки и вишню.\n\nКаждый из ребят взял с тарелки что-то одно из того, что он любит. При этом все они взяли разные фрукты или ягоды. Кто взял вишню?","options":[{"text":"Алиса"},{"text":"Боря"},{"text":"Коля"},{"text":"Денис"},{"text":"Ева"}],"condition":null,"answer":4,"points":3,"review":[{"title":"Определим выбор Алисы","text":"Алиса любит только яблоки. Значит, яблоко досталось ей."},{"title":"Определим выбор Евы","text":"Ева любит яблоки и вишню. Яблоко уже у Алисы, а каждый ребёнок взял свой фрукт или ягоду. Значит, Ева взяла вишню."}],"keyNote":null},{"number":8,"title":"Дети и взрослые в лифте","question":"Из-за ограничений по весу лифт может перевозить либо 12 взрослых, либо 20 детей. В соответствии с этими ограничениями, какое наибольшее количество детей может поехать в лифте вместе с девятью взрослыми?","options":[{"text":"3"},{"text":"4"},{"text":"5"},{"text":"6"},{"text":"8"}],"condition":null,"answer":2,"points":3,"review":[{"title":"Найдём свободную грузоподъёмность","text":"В лифте едут 9 из 12 взрослых, которых он может перевезти. Остаётся грузоподъёмность на 3 взрослых, то есть четверть от предельной."},{"title":"Переведём её в число детей","text":"Для детей полная грузоподъёмность соответствует 20 пассажирам, а четверть — 20 ÷ 4 = 5 детям."}],"keyNote":null},{"number":9,"title":"Произведения в таблице","question":"Четыре различных натуральных числа были вписаны в таблицу, а затем скрыты. Произведения чисел в каждом столбце и каждой строке указаны на рисунке. Чему равна сумма всех четырёх чисел в таблице?","options":[{"text":"10"},{"text":"12"},{"text":"13"},{"text":"14"},{"text":"15"}],"condition":{"src":"assets/grades-7-8/2024/task-09.svg","width":165,"height":172,"alt":"Таблица 2 × 2. Справа от верхней и нижней строк стоят 6 и 8, под левым и правым столбцами стоят 4 и 12."},"answer":2,"points":3,"review":[{"title":"Найдём число в верхней левой клетке","text":"Это число одновременно делит 6 и 4. Значит, оно равно 1 или 2. При числе 2 внизу левого столбца тоже было бы 2, поскольку произведение равно 4. Числа должны быть различными, поэтому в верхней левой клетке стоит 1."},{"title":"Заполним остальные клетки","text":"Вверху справа стоит 6, внизу слева — 4. Чтобы произведение нижней строки равнялось 8, внизу справа должно быть 2. В правом столбце получается 6 × 2 = 12.","image":"assets/grades-7-8/2024/solution-09-1.svg","imageWidth":178,"imageHeight":182},{"title":"Сложим числа","text":"1 + 6 + 4 + 2 = 13."}],"keyNote":null},{"number":10,"title":"Тележки из супермаркета","question":"Длина четырёх тележек из супермаркета, составленных одна в другую, 108 см. Длина десяти тележек из супермаркета, составленных одна в другую, 168 см. Какова длина одной такой тележки?","options":[{"text":"60 см"},{"text":"68 см"},{"text":"78 см"},{"text":"88 см"},{"text":"90 см"}],"condition":{"src":"assets/grades-7-8/2024/task-10.webp","width":333,"height":154,"pixelWidth":333,"pixelHeight":154,"alt":"Четыре одинаковые тележки из супермаркета вставлены одна в другую."},"answer":2,"points":3,"review":[{"title":"Найдём прибавку от одной тележки","text":"От четырёх вложенных тележек до десяти добавилось 6 тележек, а длина увеличилась на 168 − 108 = 60 см. Каждая следующая тележка увеличивает длину на 60 ÷ 6 = 10 см."},{"title":"Найдём длину первой тележки","text":"В 108 см входят длина первой тележки и три прибавки по 10 см. Длина одной тележки равна 108 − 3 × 10 = 78 см."}],"keyNote":null},{"number":11,"title":"Промежутки между кусками торта","question":"Карина испекла торт и разрезала его на десять равных кусков. Она съела один кусок, а оставшиеся куски расположила на тарелке равномерно, как показано на рисунке. Чему равна градусная мера угла между двумя соседними кусками торта?","options":[{"text":"5°"},{"text":"4°"},{"text":"3°"},{"text":"2°"},{"text":"1°"}],"condition":{"src":"assets/grades-7-8/2024/task-11.svg","width":204,"height":201,"alt":"Девять одинаковых кусков торта расположены по кругу, между соседними кусками одинаковые промежутки."},"answer":1,"points":4,"review":[{"title":"Найдём угол одного куска","text":"До того как Карина съела кусок, десять равных кусков составляли полный круг, 360°. Угол одного куска равен 360° ÷ 10 = 36°."},{"title":"Распределим свободный угол","text":"Съеденный кусок освободил 36°. Девять оставшихся кусков образуют девять одинаковых промежутков по кругу. Угол одного промежутка равен 36° ÷ 9 = 4°."}],"keyNote":null},{"number":12,"title":"Квадрат из фигур с числами","question":"Вова хочет сложить квадрат 4×4 из четырёх фигур, состоящих из равных квадратиков с числами, так, чтобы сумма чисел во всех строках и столбцах была одинаковая. Никакие фигуры переворачивать нельзя. Три фигуры, которые использует Вова, показаны на рисунке справа. Какая из следующих фигур должна быть четвёртой?","options":[{"image":"assets/grades-7-8/2024/task-12-answer-1.svg","description":"Три клетки в ряд с числами 1, 1, 3"},{"image":"assets/grades-7-8/2024/task-12-answer-2.svg","description":"Три клетки в ряд с числами 2, 1, 0"},{"image":"assets/grades-7-8/2024/task-12-answer-3.svg","description":"Три клетки в ряд с числами 1, 2, 1"},{"image":"assets/grades-7-8/2024/task-12-answer-4.svg","description":"Три клетки в ряд с числами 2, 2, 2"},{"image":"assets/grades-7-8/2024/task-12-answer-5.svg","description":"Три клетки в ряд с числами 2, 2, 3"}],"condition":{"src":"assets/grades-7-8/2024/task-12.svg","width":386,"height":112,"alt":"Первая фигура: верхний ряд из двух клеток с числами 2 и 2, под его левой клеткой ещё две с числами 1 и 2 сверху вниз. Вторая: ряд 2, 1, 3, 1 и ещё одна клетка с 1 под крайней правой. Третья: ряд 3, 1, 2 и клетка с 2 над средней клеткой."},"answer":0,"points":4,"review":[{"title":"Найдём общую сумму","text":"У средней фигуры ряд из четырёх клеток. Он занимает целую строку или целый столбец квадрата с суммой 2 + 1 + 3 + 1 = 7. Значит, все четыре строки дают в сумме 4 × 7 = 28."},{"title":"Найдём сумму четвёртой фигуры","text":"Три данные фигуры имеют суммы 7, 8 и 8. На четвёртой должно быть 28 − 7 − 8 − 8 = 5."},{"title":"Выберем и проверим деталь","text":"Только у полоски 1, 1, 3 сумма равна 5. На рисунке четыре детали образуют квадрат, в котором каждая строка и каждый столбец дают 7.","image":"assets/grades-7-8/2024/solution-12-1.svg","imageWidth":164,"imageHeight":165}],"keyNote":null},{"number":13,"title":"Два треугольника в квадрате","question":"Длина стороны квадрата – 10 м. Его поделили на части прямыми линиями, как показано на рисунке. Площади двух закрашенных треугольников равны A и B. Чему равно значение (A – B)?","options":[{"text":"0 м²"},{"text":"1 м²"},{"text":"2 м²"},{"text":"5 м²"},{"text":"10 м²"}],"condition":{"src":"assets/grades-7-8/2024/task-13.svg","width":166,"height":195,"alt":"В квадрате со стороной 10 м проведена диагональ от верхнего левого угла к нижнему правому. Точку на верхней стороне соединили с обоими нижними углами. Закрашенный треугольник A слева примыкает к левой стороне квадрата, а закрашенный треугольник B имеет вершины в нижнем правом углу, в точке на верхней стороне и в точке пересечения диагонали с отрезком из нижнего левого угла."},"answer":0,"points":4,"review":[{"title":"Добавим общий треугольник","text":"Обозначим через C площадь нижнего незакрашенного треугольника. Вместе с A он образует треугольник с левой стороной квадрата в основании. Вместе с B он образует треугольник с нижней стороной в основании.","image":"assets/grades-7-8/2024/solution-13-1.svg","imageWidth":164,"imageHeight":165},{"title":"Сравним площади","text":"У обоих больших треугольников основание и высота равны 10 м, поэтому A + C = B + C. Вычтем общую площадь C. Получим A − B = 0 м²."}],"keyNote":null},{"number":14,"title":"Рыба для пингвинят","question":"Пингвин каждый день ходит на рыбалку и приносит 12 рыб для своих двух птенцов. Каждый день он даёт первому увиденному птенцу 7 рыб, а второму – 5 рыб. Пингвинята съедают сразу всех рыб. За последние несколько дней один птенец съел 44 рыбы. Сколько рыб съел за эти дни другой птенец?","options":[{"text":"34"},{"text":"40"},{"text":"46"},{"text":"52"},{"text":"58"}],"condition":null,"answer":3,"points":4,"review":[{"title":"Установим число кормлений","text":"За день птенец получает 5 или 7 рыб, а 44 рыбы позволяют не больше шести порций по 7. При делении на 5 число 44 даёт остаток 4, а каждая порция по 7 — остаток 2. Из чисел от 0 до 6 только две такие порции дают нужный остаток. Значит, было 2 порции по 7 рыб и (44 − 14) ÷ 5 = 6 порций по 5."},{"title":"Найдём долю второго птенца","text":"Прошло 2 + 6 = 8 дней. За это время пингвин принёс 8 × 12 = 96 рыб. Второй птенец съел 96 − 44 = 52 рыбы."}],"keyNote":null},{"number":15,"title":"Конструкция из кубиков","question":"Илья составляет конструкцию: ко всем граням одного кубика он приклеивает такие же кубики. Теперь он хочет к каждой грани этой конструкции также приклеить по кубику. Сколько кубиков ему для этого потребуется?","options":[{"text":"18"},{"text":"16"},{"text":"14"},{"text":"12"},{"text":"10"}],"condition":{"src":"assets/grades-7-8/2024/task-15.svg","width":303,"height":175,"alt":"Слева показан один кубик, справа — конструкция с таким же кубиком у каждой его грани."},"answer":0,"points":4,"review":[{"title":"Рассмотрим открытые грани","text":"У каждого из шести приклеенных кубиков открыты пять граней. Получается 6 × 5 = 30 граней. Из них шесть смотрят прямо наружу, а 24 находятся у углублений между кубиками."},{"title":"Заполним углубления","text":"У каждого из 12 рёбер центрального кубика один новый кубик соприкасается сразу с двумя открытыми гранями. Так 12 кубиков закрывают все 24 грани у углублений."},{"title":"Закроем крайние грани","text":"Шесть торцевых граней требуют по одному отдельному кубику. Всего нужно 12 + 6 = 18 кубиков."}],"keyNote":null},{"number":16,"title":"Прыжки в гору и под гору","question":"Кенгуру прыгает вверх в гору, а затем обратно вниз тем же маршрутом. Когда он двигается вниз, за один прыжок он преодолевает в три раза большее расстояние, чем когда он двигается вверх. По дороге в гору длина одного прыжка Кенгуру составляет 1 метр. Всего по дороге в гору и обратно Кенгуру совершил 2024 прыжка. Какой путь он преодолел суммарно в обе стороны?","options":[{"text":"506 м"},{"text":"1012 м"},{"text":"2024 м"},{"text":"3036 м"},{"text":"4048 м"}],"condition":null,"answer":3,"points":4,"review":[{"title":"Сравним число прыжков","text":"В обе стороны кенгуру преодолевает одно и то же расстояние. Вниз он прыгает по 3 м, вверх — по 1 м. Значит, прыжков вверх было втрое больше, а прыжков вниз — 2024 ÷ 4 = 506."},{"title":"Сложим пути","text":"Расстояние в одну сторону равно 506 × 3 = 1518 м. Полный путь равен 1518 + 1518 = 3036 м."}],"keyNote":null},{"number":17,"title":"Периметры прямоугольников","question":"Большой прямоугольник разрезали на четыре меньших прямоугольника. Периметры трёх из них равны 16, 18 и 24 (смотри рисунок). Чему равен периметр четвёртого прямоугольника?","options":[{"text":"8"},{"text":"10"},{"text":"12"},{"text":"14"},{"text":"16"}],"condition":{"src":"assets/grades-7-8/2024/task-17.svg","width":165,"height":222,"alt":"Четыре прямоугольника расположены в два ряда по два. Периметры в верхнем ряду — ? и 16, в нижнем — 18 и 24."},"answer":1,"points":4,"review":[{"title":"Сложим противоположные периметры","text":"У двух прямоугольников по одной диагонали ширины в сумме дают ширину большого прямоугольника, а высоты — его высоту. Поэтому сумма их периметров равна периметру большой фигуры. Такое же равенство верно для другой диагонали."},{"title":"Найдём недостающий периметр","text":"В одной паре сумма равна 18 + 16 = 34. Во второй паре один периметр равен 24, поэтому недостающий равен 34 − 24 = 10."}],"keyNote":null},{"number":18,"title":"Свежие и сушёные грибы","question":"Вода составляет 80% массы свежих грибов. При этом вода составляет лишь 20% массы сушёных грибов. На сколько процентов уменьшается масса грибов при сушке?","options":[{"text":"60%"},{"text":"70%"},{"text":"75%"},{"text":"80%"},{"text":"85%"}],"condition":null,"answer":2,"points":4,"review":[{"title":"Возьмём 100 г свежих грибов","text":"В свежих грибах 80% воды. В 100 г свежих грибов 20 г сухого вещества. При сушке уходит вода, а масса сухого вещества остаётся прежней."},{"title":"Найдём массу после сушки","text":"В сушёных грибах 20% воды и 80% сухого вещества. Значит, 20 г — это 80% массы, а вся масса равна 25 г."},{"title":"Сравним массы","text":"Из каждых 100 г осталось 25 г. Масса уменьшилась на 75%."}],"keyNote":null},{"number":19,"title":"Оставшаяся карточка","question":"Девять карточек с различными целыми числами от 1 до 9 включительно разложены на столе лицевой стороной вниз. Саша, Миша, Кира и Даша взяли наугад по две карточки каждый. Саша сказал: «Сумма моих чисел равна 6». Миша сказал: «Разность моих чисел равна 5». Кира сказала: «Произведение моих чисел равно 18». Даша сказала: «Одно из моих чисел в два раза больше другого». Все четверо сказали правду. Какое число осталось на столе?","options":[{"text":"1"},{"text":"3"},{"text":"6"},{"text":"8"},{"text":"9"}],"condition":null,"answer":4,"points":4,"review":[{"title":"Выпишем допустимые пары","text":"У Саши возможны (1, 5) и (2, 4), у Миши — (1, 6), (2, 7), (3, 8), (4, 9). У Киры возможны (2, 9) и (3, 6), у Даши — (1, 2), (2, 4), (3, 6) и (4, 8)."},{"title":"Определим пары Саши и Киры","text":"Если у Саши (2, 4), Кире остаётся (3, 6), а все пары Даши становятся недоступны. Значит, у Саши (1, 5). Если теперь дать Кире (2, 9), то Мише остаётся (3, 8) и все пары Даши снова недоступны. Значит, у Киры (3, 6)."},{"title":"Определим оставшееся число","text":"Мише подходят (2, 7) и (4, 9). При паре (4, 9) у Даши не будет доступной пары. Поэтому Миша взял (2, 7), Даша — (4, 8), а карточка 9 осталась на столе."}],"keyNote":null},{"number":20,"title":"Угол между многоугольниками","question":"Правильный пятиугольник и правильный шестиугольник соединены с квадратом, как показано на рисунке. Чему равен угол α?","options":[{"text":"24°"},{"text":"42°"},{"text":"60°"},{"text":"69°"},{"text":"74°"}],"condition":{"src":"assets/grades-7-8/2024/task-20.svg","width":231,"height":230,"alt":"Правильный пятиугольник примыкает к квадрату снизу, правильный шестиугольник — справа. От общей вершины трёх фигур расходятся стороны пятиугольника и шестиугольника. Их концы соединены отрезком, угол α отмечен у конца на шестиугольнике."},"answer":3,"points":4,"review":[{"title":"Найдём угол у общей вершины","text":"Внутренние углы квадрата, правильного пятиугольника и правильного шестиугольника равны 90°, 108° и 120°. Вокруг общей вершины всего 360°. Угол между многоугольниками равен 360° − 90° − 108° − 120° = 42°."},{"title":"Найдём угол при основании","text":"Две стороны треугольника, выходящие из общей вершины, равны стороне квадрата. Треугольник равнобедренный, и каждый угол при основании равен (180° − 42°) ÷ 2 = 69°."}],"keyNote":null},{"number":21,"title":"Чёрточки в цифрах","question":"Цифры от 0 до 9 могут быть написаны сочетанием вертикальных и горизонтальных чёрточек. Гена выбрал три различных цифры. Вместе они содержат 5 горизонтальных и 10 вертикальных чёрточек. Чему равна сумма этих трёх цифр?","options":[{"text":"9"},{"text":"10"},{"text":"14"},{"text":"18"},{"text":"19"}],"condition":{"src":"assets/grades-7-8/2024/task-21.svg","width":412,"height":66,"alt":"Цифры на семисегментном индикаторе от 0 до 9. У 0 горят все чёрточки, кроме средней горизонтальной. У 1 горят только две правые вертикальные. У 2 горят все три горизонтальные, верхняя правая и нижняя левая вертикальные. У 3 горят все горизонтальные и обе правые вертикальные. У 4 горят средняя горизонтальная, верхняя левая и обе правые вертикальные. У 5 горят все горизонтальные, верхняя левая и нижняя правая вертикальные. У 6 горят все чёрточки, кроме верхней правой. У 7 горят верхняя горизонтальная и обе правые вертикальные. У 8 горят все чёрточки. У 9 горят все чёрточки, кроме нижней левой."},"answer":0,"points":5,"review":[{"title":"Разложим пять горизонтальных чёрточек","text":"В одной цифре от 0 до 3 горизонтальных чёрточек. Для трёх цифр возможны наборы 2 + 2 + 1, 3 + 1 + 1 и 3 + 2 + 0."},{"title":"Исключим два набора","text":"Только цифра 0 содержит две горизонтальные чёрточки, поэтому набор 2 + 2 + 1 невозможен. По одной горизонтальной чёрточке имеют 4 и 7. У них вместе 5 вертикальных, а третья цифра может дать максимум 4. Значит, набор 3 + 1 + 1 тоже не подходит."},{"title":"Восстановим три цифры","text":"Остаётся 3 + 2 + 0. Две горизонтальные чёрточки даёт 0, ни одной — 1. У 0 и 1 вместе шесть вертикальных чёрточек. У третьей цифры должны быть все три горизонтальные и четыре вертикальные, как у 8. Сумма равна 0 + 1 + 8 = 9."}],"keyNote":null},{"number":22,"title":"Единственная ось симметрии","question":"Таня хочет закрасить ещё два квадрата на рисунке так, чтобы полученное изображение имело единственную ось симметрии. Сколькими различными способами она может это сделать?","options":[{"text":"2"},{"text":"3"},{"text":"4"},{"text":"5"},{"text":"6"}],"condition":{"src":"assets/grades-7-8/2024/task-22.svg","width":194,"height":196,"alt":"Сетка 4 × 4. В верхней строке закрашена вторая клетка слева, во второй строке — третья слева."},"answer":4,"points":5,"review":[{"title":"Перечислим оси квадрата","text":"У сетки четыре возможные оси симметрии: горизонтальная, вертикальная и две диагональные. Нумеруем строки сверху вниз, а столбцы слева направо. Изначально закрашены клетки (1, 2) и (2, 3)."},{"title":"Проверим оси без закрашенных клеток","text":"Для горизонтальной оси нужно закрасить отражения (4, 2) и (3, 3). Для вертикальной — (1, 3) и (2, 2). Для диагонали из верхнего левого в нижний правый угол — (2, 1) и (3, 2). Получается по одному способу для каждой оси."},{"title":"Проверим вторую диагональ","text":"У диагонали из нижнего левого в верхний правый угол клетка (2, 3) уже лежит на оси. Клетке (1, 2) нужно добавить отражение (3, 4). Последнюю клетку можно выбрать среди трёх свободных клеток на оси. Всего 1 + 1 + 1 + 3 = 6 способов. Все шесть наборов различны, поэтому ни у одного нет второй оси.","image":"assets/grades-7-8/2024/solution-22-1.svg","imageWidth":355,"imageHeight":223}],"keyNote":null},{"number":23,"title":"Три полукруга в прямоугольнике","question":"На рисунке изображены три полукруга, расположенные внутри прямоугольника. Средний полукруг касается двух соседних полукругов, а они, в свою очередь, касаются коротких сторон прямоугольника. Самый большой полукруг также касается верхней длинной стороны прямоугольника. Кратчайшие расстояния от этой стороны до двух других полукругов равны 5 см и 7 см. Чему равен периметр прямоугольника?","options":[{"text":"82 см"},{"text":"92 см"},{"text":"96 см"},{"text":"108 см"},{"text":"120 см"}],"condition":{"src":"assets/grades-7-8/2024/task-23.svg","width":417,"height":160,"alt":"Три полукруга опираются диаметрами на нижнюю сторону прямоугольника. Слева самый большой полукруг касается верхней стороны. Расстояние от вершины среднего полукруга до верхней стороны — 5 см, от вершины правого — 7 см. Длина прямоугольника — 36 см."},"answer":1,"points":5,"review":[{"title":"Выразим радиусы через высоту","text":"Пусть высота прямоугольника равна h см. Диаметры всех полукругов лежат на нижней стороне, поэтому радиусы равны h, h − 5 и h − 7."},{"title":"Воспользуемся длиной основания","text":"Три диаметра вместе составляют 36 см. Значит, сумма радиусов равна 18 см. Получаем h + (h − 5) + (h − 7) = 18, откуда 3h = 30 и h = 10."},{"title":"Найдём периметр","text":"Стороны прямоугольника равны 36 см и 10 см. Периметр равен 2 × (36 + 10) = 92 см."}],"keyNote":null},{"number":24,"title":"Мяч по кругу","question":"Группа из 50 учеников села в круг. Они бросают мяч по кругу. Каждый ученик, получивший мяч, бросает его по направлению против часовой стрелки шестому по счёту от себя ученику, и тот его ловит. Федя получил мяч сто раз. Сколько учеников за это время так и не получили мяч?","options":[{"text":"0"},{"text":"8"},{"text":"10"},{"text":"25"},{"text":"40"}],"condition":null,"answer":3,"points":5,"review":[{"title":"Проследим чётность","text":"Пронумеруем места против часовой стрелки. При каждом броске номер увеличивается на 6 с переходом через 50. Поскольку оба числа чётные, мяч попадает только на места той же чётности, что у Феди."},{"title":"Найдём длину цикла","text":"Мяч возвращается к Феде, когда 6 × число бросков делится на 50. Это равносильно тому, что 3 × число бросков делится на 25. Числа 3 и 25 взаимно просты, так что первый возврат происходит через 25 бросков."},{"title":"Сосчитаем учеников","text":"За полный цикл мяч побывал у 25 разных учеников. По условию Федя получил его сто раз, так что полный цикл уже прошёл. Остальные 50 − 25 = 25 учеников мяч не получили."}],"keyNote":null},{"number":25,"title":"Пирамида произведений","question":"На рисунке изображена пирамида из квадратов, в которые Даня хочет вписать натуральные числа так, чтобы каждый квадрат в средней и верхней строках содержал произведение двух чисел, написанных непосредственно под ним. Если самое верхнее число 720, то сколько различных значений может принимать число n?","options":[{"text":"1"},{"text":"4"},{"text":"5"},{"text":"6"},{"text":"8"}],"condition":{"src":"assets/grades-7-8/2024/task-25.svg","width":144,"height":144,"alt":"Пирамида состоит из трёх клеток внизу, двух посередине и одной наверху. В верхней клетке число 720, в центральной клетке нижнего ряда — n."},"answer":3,"points":5,"review":[{"title":"Запишем произведения","text":"Обозначим крайние числа нижнего ряда через a и b. Тогда в среднем ряду стоят a × n и b × n, а наверху — a × b × n². Значит, n² делит 720."},{"title":"Найдём все подходящие n","text":"720 = 2⁴ × 3² × 5. В n может быть до двух множителей 2 и до одного множителя 3. Множителя 5 в n быть не может, поскольку в n² он встретился бы дважды. Получаются 1, 2, 3, 4, 6 и 12."},{"title":"Проверим выполнимость","text":"Для каждого из этих n можно взять a = 1 и b = 720 ÷ n². Оба числа натуральные, и наверху действительно получается 720. Всего шесть значений."}],"keyNote":null},{"number":26,"title":"Корзины с яйцами","question":"Фермер продаёт куриные и утиные яйца. Он привёз на рынок шесть корзин, в которых находится 4, 6, 12, 13, 22 и 29 яиц соответственно. Первый покупатель купил одну корзину яиц. После этого фермер заметил, что у него осталось в два раза больше куриных яиц, чем утиных. Сколько яиц купил первый покупатель?","options":[{"text":"4"},{"text":"12"},{"text":"13"},{"text":"22"},{"text":"29"}],"condition":null,"answer":4,"points":5,"review":[{"title":"Сосчитаем яйца","text":"В шести корзинах было 4 + 6 + 12 + 13 + 22 + 29 = 86 яиц."},{"title":"Проверим остаток от деления","text":"После покупки на каждое утиное яйцо осталось по два куриных, поэтому общее число оставшихся яиц делится на 3. Число 86 даёт остаток 2 при делении на 3. Такой же остаток должно давать число купленных яиц."},{"title":"Выберем корзину","text":"Только 29 даёт остаток 2 при делении на 3. Покупатель купил 29 яиц."}],"keyNote":null},{"number":27,"title":"Три угла на клетчатой бумаге","question":"Три угла построены на клетчатом листе бумаги, как показано на рисунке, и отмечены буквами α, β и γ. Чему равно значение (α + β + γ)?","options":[{"text":"60°"},{"text":"70°"},{"text":"75°"},{"text":"90°"},{"text":"120°"}],"condition":{"src":"assets/grades-7-8/2024/task-27.svg","width":306,"height":238,"alt":"На нижней линии сетки вершины углов α, β и γ находятся в точках (0, 0), (2, 0) и (4, 0). Из каждой вершины идут отрезки к двум точкам на три клетки выше: (1, 3) и (3, 3)."},"answer":3,"points":5,"review":[{"title":"Найдём прямоугольный треугольник","text":"Возьмём нижнюю левую вершину угла α, верхнюю левую точку и точку пересечения диагоналей. Две диагонали идут по клеткам под 45° к горизонтали в разные стороны, поэтому угол при их пересечении равен 90°."},{"title":"Перенесём углы по параллельным линиям","text":"При верхней левой вершине треугольника получаются углы β и γ. Наклонные отрезки, образующие эти углы, попарно параллельны соответствующим отрезкам у нижних вершин. Значит, третий угол треугольника равен β + γ.","image":"assets/grades-7-8/2024/solution-27-1.svg","imageWidth":256,"imageHeight":204},{"title":"Сложим углы","text":"В треугольнике α + (β + γ) + 90° = 180°. Значит, α + β + γ = 90°."}],"keyNote":null},{"number":28,"title":"Монеты капитана Флинта","question":"Капитан Флинт попросил четырёх пиратов написать, сколько золотых, серебряных и бронзовых монет было в сундуке с сокровищами. Они написали это на листке. Однако, к несчастью, часть листка оторвалась и потерялась. Известно, что только один из четырёх пиратов написал правду. Остальные трое соврали во всех трёх ответах. Также известно, что всего в сундуке было 30 монет. Кто из пиратов написал правду?","options":[{"text":"Том"},{"text":"Джек"},{"text":"Билл"},{"text":"Джим"},{"text":"Нельзя определить"}],"condition":{"src":"assets/grades-7-8/2024/task-28.svg","width":388,"height":204,"alt":"На листке три столбца: золотые, серебряные, бронзовые. В строке Тома сохранились 9 серебряных и 11 бронзовых. У Джека — 7 золотых и 12 бронзовых. У Билла — 10 золотых и 10 бронзовых. У Джима — 9 золотых и 10 серебряных."},"answer":1,"points":5,"review":[{"title":"Проверим Тома и Билла","text":"Если прав Том, золотых монет было 30 − 9 − 11 = 10. То же число назвал Билл, хотя он должен был ошибиться во всех трёх ответах. Если прав Билл, серебряных было 30 − 10 − 10 = 10. То же число назвал Джим."},{"title":"Проверим Джима","text":"Если прав Джим, бронзовых монет было 30 − 9 − 10 = 11. То же число назвал Том. Следовательно, остаётся Джек."},{"title":"Восстановим ответ Джека","text":"Джек записал 7 золотых и 12 бронзовых, поэтому серебряных было 30 − 7 − 12 = 11. Все сохранившиеся ответы других пиратов отличаются от этих чисел в соответствующих столбцах. Правду написал Джек."}],"keyNote":null},{"number":29,"title":"Две встречи автомобилистов","question":"Первый автомобилист поехал из точки A в точку B и сразу же вернулся обратно в точку A. Второй автомобилист поехал из точки B в точку A и сразу же вернулся обратно в точку B. Они ехали по одной и той же дороге, стартовали в одно и то же время, и скорость каждого из них была постоянной на протяжении всего пути. Скорость первого автомобилиста в 3 раза выше скорости второго. В первый раз они встретились через 15 минут после старта. Через какое время после старта они встретились во второй раз?","options":[{"text":"20 мин"},{"text":"25 мин"},{"text":"30 мин"},{"text":"35 мин"},{"text":"45 мин"}],"condition":null,"answer":2,"points":5,"review":[{"title":"Выразим расстояние через скорость","text":"Пусть скорость второго автомобилиста равна v. Тогда скорость первого — 3v. За 15 минут до первой встречи они вместе проехали всё расстояние AB, равное 15 × (3v + v) = 60v."},{"title":"Найдём момент разворота","text":"Первому нужно 60v ÷ 3v = 20 минут, чтобы доехать до B. За это время второй удалился от B на 20v. После разворота оба едут в сторону A, и первый сокращает расстояние со скоростью 3v − v = 2v."},{"title":"Найдём момент второй встречи","text":"Первый догоняет второго через 20v ÷ 2v = 10 минут после разворота. Это происходит через 20 + 10 = 30 минут после старта."}],"keyNote":null},{"number":30,"title":"Площадь BCDF","question":"На рисунке AB = 2 см, BC = 6 см, CD = 8 см, DE = 4 см и ∠ACE = 90°. Чему равна площадь четырёхугольника BCDF?","options":[{"text":"24 см²"},{"text":"28 см²"},{"text":"32 см²"},{"text":"36 см²"},{"text":"48 см²"}],"condition":{"src":"assets/grades-7-8/2024/task-30.svg","width":324,"height":232,"alt":"На вертикальном отрезке AC точка B лежит между A и C. На горизонтальном отрезке CE точка D лежит между C и E. Точка F — пересечение отрезков AD и BE."},"answer":1,"points":5,"review":[{"title":"Разобьём четырёхугольник","text":"Проведём CF. Пусть x — площадь треугольника BCF, а y — площадь CFD. На схеме FM и FN — высоты к сторонам AC и CE. Треугольники ABF и BCF имеют общую высоту FM, а их основания AB и BC относятся как 2 : 6. Поэтому площадь ABF равна x/3. С общей высотой FN площадь FDE равна y/2, поскольку DE : CD = 4 : 8.","image":"assets/grades-7-8/2024/solution-30-1.svg","imageWidth":306,"imageHeight":222},{"title":"Вычислим площади больших треугольников","text":"AC = 2 + 6 = 8 см, CE = 8 + 4 = 12 см. Площади прямоугольных треугольников ACD и BCE равны 8 × 8 ÷ 2 = 32 см² и 6 × 12 ÷ 2 = 36 см². Разбив их на части, получаем 4x/3 + y = 32 и x + 3y/2 = 36."},{"title":"Найдём сумму x + y","text":"Умножим первое уравнение на 3, второе на 2. Получаем 4x + 3y = 96 и 2x + 3y = 72. Вычитание даёт 2x = 24, то есть x = 12. Тогда y = 16, а площадь BCDF равна 12 + 16 = 28 см²."}],"keyNote":null}]}];
'use strict';

(() => {
  const archive = globalThis.KENGURU_ARCHIVE ??= {};
  const visual = globalThis.KenguruVisual;
  const cyrillicAnswers = 'АБВГД';

  function circleComparison(step, frame) {
    const outline = '#54877e';
    const fill = ['#347d75', '#43998c', '#60a99d', '#2e807c'];
    const ink = '#172e34';
    const radius = 43;
    const quarter = 'M0 0H43A43 43 0 0 0 0 -43Z';
    if (step === 1) {
      const opacity = .25 + .75 * visual.reveal(frame);
      return visual.svg(`<rect x="225" y="20" width="190" height="190" rx="3" fill="#f1f6ee" stroke="${outline}" stroke-width="2"/>
        <path d="M320 115H415A95 95 0 0 0 320 20Z" fill="${fill[0]}" opacity="${opacity}"/>
        <path d="M320 123V130M415 123V130M320 126H415" fill="none" stroke="${ink}" stroke-width="2"/>
        <text x="367.5" y="154" fill="${ink}" font-size="17" text-anchor="middle">радиус</text>`,
      'Радиус четверти круга равен половине стороны квадрата', '0 0 640 230', 'worked-scene');
    }
    if (step !== 2) return null;

    const far = radius;
    const offsets = [
      [[-far, far], [-far, -far], [far, -far], [far, far]],
      [[0, 0], [0, 0], [0, 0], [0, 0]],
      [[-far, 0], [-far, 0], [far, 0], [far, 0]],
      [[0, far], [-far, -far], [far, -far], [0, far]],
    ];
    const groups = offsets.map((pieces, index) => {
      const x = index % 2 === 0 ? 222 : 418;
      const y = index < 2 ? 95 : 254;
      const start = index * .38;
      const turn = index === 1 ? 0 : 180 * visual.reveal((frame - start) * 2.5);
      const remaining = 1 - visual.reveal((frame - start - 1.2) * 1.15);
      const paths = pieces.map(([dx, dy], piece) =>
        `<path d="${quarter}" fill="${fill[piece]}" stroke="#fffefa"
          stroke-width=".6" transform="translate(${x + dx * remaining} ${y + dy * remaining}) rotate(${90 * piece + turn})"/>`
      ).join('');
      return `<rect x="${x - radius}" y="${y - radius}" width="${radius * 2}" height="${radius * 2}"
        fill="#f1f6ee" stroke="${outline}" stroke-width="1.6"/>${paths}
        <text x="${x - 96}" y="${y + 6}" fill="${ink}" font-size="20" text-anchor="middle">${cyrillicAnswers[index]}</text>`;
    });
    return visual.svg(groups.join(''), 'Четыре четверти каждого рисунка складываются в целый круг',
      '102 0 432 348', 'worked-scene');
  }

  const editions = [...(globalThis.KENGURU_GRADES_7_8 ?? []), ...(globalThis.KENGURU_JUNIOR_SENIOR ?? [])];
  for (const edition of editions) {
    const answerLetters = [...(edition.answerLetters ?? cyrillicAnswers)];
    const {id, year, label, grades, tasksUrl, answersUrl, solutionUrl, cards} = edition;
    const lessons = [];
    const scenes = [];

    for (const {number, title, question, questionNote, options, condition, answer, points, review, keyNote} of cards) {
      const hasReview = review.length > 0;
      const choiceImages = options.map(option => option.image);
      const choices = options.map(option => option.text ?? '');
      const answerLetter = answerLetters[answer];
      const steps = [['Условие', 'Условие задачи', '']];
      for (const [index, stage] of review.entries()) {
        const final = index === review.length - 1;
        steps.push([final ? 'Ответ' : 'Шаг ' + (index + 1), stage.title, stage.text]);
      }
      if (!hasReview) {
        steps.push(['Ответ', 'Проверка по ключу', keyNote ?? (answerLetter ? 'Правильный вариант — ' + answerLetter + '.' : 'Сверь решение с ответом в PDF.')]);
      }

      lessons.push({
        number, title, short: title, question, questionNote, points, answer, choices, choiceImages,
        choiceLayout: {condition, options}, conditionImage: condition?.src, conditionAlt: condition?.alt,
        hideIntroText: true, paperEdition: !hasReview, showCompletedStep: hasReview,
        officialValueKey: answer === null,
        steps,
      });

      const keyedAnswer = visual.answerScene({letter: answerLetter, value: choices[answer]});
      scenes.push((step, frame) => {
        if (!step) return '';
        if (!hasReview) return keyedAnswer;
        const stage = review[step - 1];
        const animation = id === '2026-7-8' && number === 1 ? circleComparison(step, frame) : null;
        return animation ?? (visual.workedScene(stage, frame)
          || (step === review.length ? keyedAnswer : ''));
      });
    }
    archive[id] = {id, year, label, grades, answerLetters, sources: {tasksUrl, answersUrl, solutionUrl}, lessons, scenes};
  }
})();

register((globalThis.KENGURU_ARCHIVE["2024-7-8"] ?? [].concat(globalThis.KENGURU_ARCHIVE[2024] ?? []).find(edition => edition.id === "2024-7-8")), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
